    ,sum(case when complete_datetime is not null then order_cnt end) as completed_order_cnt
    ,sum(case when cancel_datetime is not null then order_cnt end) as cancelled_order_cnt
    ,sum(case when is_returned_item = 1 then order_cnt end) as returned_order_cnt

