CREATE TEMPORARY VIEW selected_user_exps_${grass_region_without_quote} AS
select
    user_id
    ,exp_group_id
    ,local_date
from
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where
    grass_region in (${grass_region})
    and local_date between date_add(date(${local_date}),-14) and date(${local_date})
    and is_dim_join = 1
    and is_rcmd_whitelist = 1
;

