    ,is_cod_order

    ,sum(order_cnt) as order_cnt
    ,sum(paid_order_cnt) as paid_order_cnt
    ,sum(completed_order_cnt) as completed_order_cnt
    ,sum(cancelled_order_cnt) as cancelled_order_cnt
    ,sum(returned_order_cnt) as returned_order_cnt

    ,sum(item_cnt) as item_cnt
    ,sum(paid_item_cnt) as paid_item_cnt
    ,sum(completed_item_cnt) as completed_item_cnt
    ,sum(cancelled_item_cnt) as cancelled_item_cnt
    ,sum(returned_item_cnt) as returned_item_cnt

    ,sum(model_cnt) as model_cnt
    ,sum(paid_model_cnt) as paid_model_cnt
    ,sum(completed_model_cnt) as completed_model_cnt
    ,sum(cancelled_model_cnt) as cancelled_model_cnt
    ,sum(returned_model_cnt) as returned_model_cnt

    ,sum(gmv) as gmv
