    ,sum(completed_gmv) as completed_gmv
    ,sum(cancelled_gmv) as cancelled_gmv
    ,sum(returned_gmv) as returned_gmv
from
    behavior_data_joined_${grass_region_without_quote} as t1
inner join
    selected_user_exps_${grass_region_without_quote} as t2
on
