    ,sum(completed_item_cnt) as completed_item_cnt
    ,sum(cancelled_item_cnt) as cancelled_item_cnt
    ,sum(returned_item_cnt) as returned_item_cnt

    ,sum(model_cnt) as model_cnt
    ,sum(paid_model_cnt) as paid_model_cnt
    ,sum(completed_model_cnt) as completed_model_cnt
    ,sum(cancelled_model_cnt) as cancelled_model_cnt
    ,sum(returned_model_cnt) as returned_model_cnt

    ,sum(gmv) as gmv
    ,sum(paid_gmv) as paid_gmv
    ,sum(completed_gmv) as completed_gmv
    ,sum(cancelled_gmv) as cancelled_gmv
    ,sum(returned_gmv) as returned_gmv
FROM exp_group_data_filter_${grass_region_without_quote}
LATERAL VIEW EXPLODE(array_union(array_union(scenario_tags, COALESCE(source1_scenario_tags, array())), COALESCE(source2_scenario_tags, array()))) AS scenario_tag
GROUP BY
    local_date
    ,exp_group_id
    ,is_ads
    ,is_cod_order
    ,scenario_tag

UNION ALL

SELECT
    local_date
    ,exp_group_id
    ,is_ads
    ,is_cod_order
    ,feature_detail
    ,scenario_tag

    ,sum(order_cnt) as order_cnt
    ,sum(paid_order_cnt) as paid_order_cnt
    ,sum(completed_order_cnt) as completed_order_cnt
    ,sum(cancelled_order_cnt) as cancelled_order_cnt
    ,sum(returned_order_cnt) as returned_order_cnt

    ,sum(item_cnt) as item_cnt
    ,sum(paid_item_cnt) as paid_item_cnt
    ,sum(completed_item_cnt) as completed_item_cnt
    ,sum(cancelled_item_cnt) as cancelled_item_cnt
    ,sum(returned_item_cnt) as returned_item_cnt

    ,sum(model_cnt) as model_cnt
    ,sum(paid_model_cnt) as paid_model_cnt
    ,sum(completed_model_cnt) as completed_model_cnt
    ,sum(cancelled_model_cnt) as cancelled_model_cnt
    ,sum(returned_model_cnt) as returned_model_cnt

    ,sum(gmv) as gmv
    ,sum(paid_gmv) as paid_gmv
    ,sum(completed_gmv) as completed_gmv
    ,sum(cancelled_gmv) as cancelled_gmv
    ,sum(returned_gmv) as returned_gmv
FROM feature_tag_data_${grass_region_without_quote}
GROUP BY
    local_date
    ,exp_group_id
    ,is_ads
    ,is_cod_order
    ,feature_detail
    ,scenario_tag
;

--sql_divide_splitter--

insert overwrite table ${schema}.dws_sr_data_warehouse_platform_exp_level_order_metrics_1d
