    ,order_cnt
    ,paid_order_cnt
    ,completed_order_cnt
    ,cancelled_order_cnt
    ,returned_order_cnt

    ,item_cnt
    ,paid_item_cnt
    ,completed_item_cnt
    ,cancelled_item_cnt
    ,returned_item_cnt

    ,model_cnt
    ,paid_model_cnt
    ,completed_model_cnt
    ,cancelled_model_cnt
    ,returned_model_cnt

    ,gmv
    ,paid_gmv
    ,completed_gmv
    ,cancelled_gmv
    ,returned_gmv

    ,is_ads
    ,scenario_tag
    ,local_date
from
